import {resultsRefinementPreservedSource} from './preserved-source';
import {test} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';import {resultsModel,countedScore,SCORE_COUNT_MS} from '../src/ui/results-model';import {appearancePreview} from '../src/presentation/cosmetic-art';import {SKINS,EYES,HATS} from '../src/presentation/cosmetics';import {OutbreakRules} from '../src/game/outbreak';import {FreezeRules,FREEZE} from '../src/game/freeze-tag';import {ClassicRules,CLASSIC} from '../src/game/classic-tag';import type {LobbyState} from '../src/network/protocol';
const lobby=(n:number):LobbyState=>{const players=Array.from({length:n},(_,slot)=>({id:'frog:'+slot,slot,name:'Frog '+slot,kind:slot?'cpu' as const:'human' as const,connected:!slot,ready:true,appearance:{skin:SKINS[slot%SKINS.length].id,eyes:EYES[slot%EYES.length].id,hat:HATS[slot%HATS.length].id}}));return {code:'ABC234',arenaId:'sunny-pond',phase:'game',hostId:'frog:0',players,roster:structuredClone(players),notice:'',reconnectSeconds:30};};
for(const mode of['poison','freeze','classic'])for(const n of[2,3,8])test(`${mode} ${n}-frog actual authoritative results preserve ranks, all cosmetics and exact round deltas`,()=>{const t={announcementTicks:0,countdownTicks:0,graceTicks:60},r=mode==='freeze'?new FreezeRules(Array.from({length:n},(_,i)=>i),0,{...FREEZE,...t}):mode==='classic'?new ClassicRules(Array.from({length:n},(_,i)=>i),0,{...CLASSIC,...t}):new OutbreakRules(Array.from({length:n},(_,i)=>i),0,t);r.advanceClock(0);r.infect(mode==='classic'?3600:600,mode==='classic'?[]:Array.from({length:n-1},(_,i)=>[0,i+1]as[number,number]));const state=r.view(3600),before=JSON.stringify(state),room=lobby(n),model=resultsModel(state,room,'frog:0');assert.equal(model.frogs.length,n);for(const f of model.frogs){const p=state.players[f.slot];assert.equal(f.rank,p.finalPlace);assert.equal(f.total,p.totalPoints);assert.equal(f.previous+f.delta,f.total);assert.deepEqual(f.appearance,room.roster![f.slot].appearance);assert.equal(f.cpu,f.slot!==0);assert.equal(f.status,f.cpu?'CPU':'');assert.equal(f.roundWinner,state.roundWinners.includes(f.slot));}assert.equal(JSON.stringify(state),before);for(const group of model.groups)assert.ok(group.frogs.every(f=>f.rank===group.rank&&group.rank<=3));});
test('tied podium follows competition placements without inventing second place or breaking shared champions',()=>{const r=new OutbreakRules([0,1,2,3],0);r.phase='match-results';r.totals=[40,40,10,0];const view=r.view(0),model=resultsModel(view,lobby(4),'frog:1');assert.deepEqual(model.groups.map(g=>[g.rank,g.frogs.map(f=>f.slot)]),[[1,[0,1]],[3,[2]]]);assert.deepEqual(model.frogs.filter(f=>f.champion).map(f=>f.slot),[0,1]);assert.ok(model.tiedPodium);assert.equal(model.frogs.find(f=>f.slot===1)!.local,true);});
test('eight tied winners all share first and remain represented on the podium and full board',()=>{const r=new OutbreakRules([0,1,2,3,4,5,6,7],0);r.phase='match-results';r.totals=Array(8).fill(8);const m=resultsModel(r.view(0),lobby(8),'frog:0');assert.equal(m.groups.length,1);assert.equal(m.groups[0].frogs.length,8);assert.ok(m.frogs.every(f=>f.rank===1&&f.champion&&f.tied));});
test('previous totals are authoritative total minus round award; reconnects and departed slots retain their frozen-roster portraits',()=>{const r=new OutbreakRules([0,1,2],0);r.totals=[15.2,32.3,7.7];r.records[0].roundPoints=0;r.records[1].roundPoints=12.1;r.records[2].roundPoints=2.2;r.presence.set(2,false,0,false);const room=lobby(3);room.players=room.players.filter(p=>p.slot!==2);room.players[0].connected=false;const m=resultsModel(r.view(0),room,'frog:0');assert.equal(m.frogs.find(f=>f.slot===1)!.previous,20.2);const left=m.frogs.find(f=>f.slot===2)!;assert.equal(left.status,'Left');assert.equal(left.name,'Frog 2');assert.deepEqual(left.appearance,room.roster![2].appearance);assert.equal(m.frogs.find(f=>f.slot===0)!.status,'Offline');});
test('short eased count is monotonic and ends at exact server totals including zero and fractions',()=>{for(const[from,to]of[[0,0],[20.2,32.3],[0,999.9],[1.1,1.2]]){let previous=from;assert.equal(countedScore(from,to,0),from);for(let ms=0;ms<=SCORE_COUNT_MS;ms+=10){const now=countedScore(from,to,ms);assert.ok(now>=previous);assert.ok(now<=to);previous=now;}assert.equal(countedScore(from,to,SCORE_COUNT_MS),to);assert.equal(countedScore(from,to,SCORE_COUNT_MS+100),to);}});
test('portraits reuse every actual catalog skin, pattern, eye and hat without custom result artwork',()=>{for(let i=0;i<SKINS.length;i++){const a={skin:SKINS[i].id,eyes:EYES[i%EYES.length].id,hat:HATS[i%HATS.length].id},svg=appearancePreview(a);assert.ok(svg.includes('#'+SKINS[i].color.toString(16).padStart(6,'0')));assert.ok(svg.includes(a.eyes));}const source=readFileSync('src/ui/results-ui.ts','utf8');assert.match(source,/appearancePreview\(f.appearance\)/);assert.doesNotMatch(source,/\.send\(|\.nextRound\(|\.returnLobby\(|setTransform|applyImpulse|localStorage/);});
